#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
void gen(vector<ll>& a, int i, int n, ll cur, vector<ll>& out) {
    if (i == n) { out.push_back(cur); return; }
    gen(a, i+1, n, cur,       out);
    gen(a, i+1, n, cur+a[i], out);
}
int main() {
    int n; ll T; cin >> n >> T;
    vector<ll> a(n);
    for (auto& x : a) cin >> x;
    int half = n / 2;
    vector<ll> L, R;
    gen(a, 0,    half, 0, L);
    gen(a, half, n,    0, R);
    sort(L.begin(), L.end());
    ll count = 0;
    for (ll s : R) {
        ll need = T - s;
        auto lo = lower_bound(L.begin(), L.end(), need);
        auto hi = upper_bound(L.begin(), L.end(), need);
        count += hi - lo;
    }
    cout << count << "\n";
    return 0;
}

