import java.util.*;
public class Main {
    static List<Long> gen(long[] a, int lo, int hi) {
        List<Long> res = new ArrayList<>();
        int sz = hi - lo;
        for (int mask = 0; mask < (1 << sz); mask++) {
            long s = 0;
            for (int b = 0; b < sz; b++) if ((mask >> b & 1) == 1) s += a[lo + b];
            res.add(s);
        }
        return res;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); long T = sc.nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();
        int half = n / 2;
        List<Long> L = gen(a, 0, half);
        List<Long> R = gen(a, half, n);
        Collections.sort(L);
        long count = 0;
        for (long s : R) {
            long need = T - s;
            int lo2 = Collections.binarySearch(L, need);
            if (lo2 < 0) continue;
            int i = lo2; while (i > 0 && L.get(i-1) == need) i--;
            int j = lo2; while (j < L.size()-1 && L.get(j+1) == need) j++;
            count += j - i + 1;
        }
        System.out.println(count);
    }
}
